<template><div><h3>资料修改审核</h3><el-table :data="requests" v-loading="loading" style="margin-top:16px"><el-table-column label="头像" width="70"><template #default="{row}"><el-avatar :size="40" :src="row.counselor?.photoUrl"><el-icon><UserFilled /></el-icon></el-avatar></template></el-table-column><el-table-column label="辅导员"><template #default="{row}">{{ row.counselor?.name }}</template></el-table-column><el-table-column label="修改内容" min-width="240"><template #default="{row}"><div v-for="(item, idx) in formatChanges(row.changesJson)" :key="idx" style="margin:2px 0"><el-tag size="small" effect="plain" type="info" style="margin-right:4px">{{ item.label }}</el-tag><span>{{ item.value }}</span></div></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="statusTag(row.status)" size="small">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column prop="createdAt" label="申请时间" width="180" /><el-table-column label="操作" width="200"><template #default="{row}"><el-button v-if="row.status==='PENDING'" size="small" type="success" @click="approve(row.id)">通过</el-button><el-button v-if="row.status==='PENDING'" size="small" type="danger" @click="reject(row.id)">驳回</el-button></template></el-table-column></el-table></div></template>
<script setup>import { ref, onMounted } from 'vue'; import api from '../../utils/request'; import { ElMessage, ElMessageBox } from 'element-plus'; const requests = ref([]); const colleges = ref([]); const loading = ref(false); const fieldMap = { name:'姓名', gender:'性别', collegeId:'学院', politicalStatus:'政治面貌', highestEducation:'最高学历', officeAddress:'办公地址', phone:'电话', email:'邮箱', photoUrl:'头像' }; onMounted(async () => { loading.value=true; try { const [r,c] = await Promise.all([api.get('/admin/profile-edit-requests'), api.get('/public/colleges')]); requests.value=r.data; colleges.value=c.data } catch(e) {} finally { loading.value=false } }); function formatChanges(json){ try { const obj=JSON.parse(json); return Object.entries(obj).map(([k,v]) => { let val=v; if (k==='collegeId' && colleges.value.length) { const found = colleges.value.find(c=>c.id==v); val=found?found.name:v } return { label:fieldMap[k]||k, value:val } }) } catch{return[]} } function statusTag(s){const m={PENDING:'warning',APPROVED:'success',REJECTED:'danger'};return m[s]||'info'} function statusLabel(s){const m={PENDING:'审核中',APPROVED:'已通过',REJECTED:'已驳回'};return m[s]||s} async function approve(id){try{await api.post('/admin/profile-edit-requests/'+id+'/approve');ElMessage.success('已通过');loadData()}catch(e){}} async function reject(id){try{const {value}=await ElMessageBox.prompt('驳回原因','驳回',{type:'warning'});await api.post('/admin/profile-edit-requests/'+id+'/reject',{comment:value});ElMessage.success('已驳回');loadData()}catch(e){}} async function loadData(){loading.value=true;try{const {data}=await api.get('/admin/profile-edit-requests');requests.value=data}catch(e){}finally{loading.value=false}}</script>
